import sys, heapq
def main():
    data = sys.stdin.buffer.read().split()
    N = int(data[0]); Q = int(data[1])
    INF = 1 << 62
    nxt = {0: N + 1}
    prv = {N + 1: 0}
    seat = {}
    h = []
    push = heapq.heappush
    def seg(a, b):
        if a == 0 and b == N + 1:
            push(h, (-INF, 1, a, b))
        elif a == 0:
            if b > 1:
                push(h, (-(b - 1), 1, a, b))
        elif b == N + 1:
            if a < N:
                push(h, (-(N - a), N, a, b))
        elif b - a >= 2:
            m = (a + b) // 2
            push(h, (-(m - a), m, a, b))
    seg(0, N + 1)
    MOD = 10 ** 9 + 7
    total = 0
    k = 0
    idx = 2
    for _ in range(Q):
        op = data[idx]; sid = data[idx + 1]; idx += 2
        if op == b"A":
            while True:
                d, s, a, b = heapq.heappop(h)
                if nxt.get(a) == b:
                    break
            nxt[a] = s; prv[s] = a; nxt[s] = b; prv[b] = s
            seg(a, s); seg(s, b)
            seat[sid] = s
            k += 1
            total = (total + k * s) % MOD
        else:
            p = seat.pop(sid)
            a = prv.pop(p); b = nxt.pop(p)
            nxt[a] = b; prv[b] = a
            seg(a, b)
    print(total)
main()

import sys
def main():
    d = sys.stdin.buffer.read().split()
    n = int(d[0])
    A = list(map(int, d[1:1 + n])); B = list(map(int, d[1 + n:1 + 2 * n]))
    if sorted(A) != sorted(B):
        print(-1); return
    pos = {v: i for i, v in enumerate(B)}
    p = [pos[v] for v in A]
    seen = [False] * n
    cyc = 0
    for i in range(n):
        if not seen[i]:
            cyc += 1
            j = i
            while not seen[j]:
                seen[j] = True; j = p[j]
    tree = [0] * (n + 1)
    inv = 0
    for i in range(n - 1, -1, -1):
        j = p[i]
        while j > 0:
            inv += tree[j]; j -= j & -j
        j = p[i] + 1
        while j <= n:
            tree[j] += 1; j += j & -j
    print(n - cyc, inv)
main()

