def main():
    d = sys.stdin.buffer.read().split()
    R, C = int(d[0]), int(d[1])
    h = [0] * C
    total = 0
    for r in range(R):
        row = d[2 + r]
        for c in range(C):
            if row[c] == 49:
                h[c] += 1
            else:
                h[c] = 0
        st = []
        s = [0] * C
        for c in range(C):
            hc = h[c]
            while st and h[st[-1]] >= hc:
                st.pop()
            if st:
                p = st[-1]
                v = s[p] + hc * (c - p)
            else:
                v = hc * (c + 1)
            s[c] = v
            total += v
            st.append(c)
    print(total)
