import sys
def main():
    d = sys.stdin.buffer.read().split()
    n, w, k = int(d[0]), int(d[1]), int(d[2])
    a = list(map(int, d[3:3 + n]))
    vals = sorted(set(a)); m = len(vals)
    rank = {v: i + 1 for i, v in enumerate(vals)}
    r = [rank[x] for x in a]
    tree = [0] * (m + 1)
    LOG = 1
    while LOG * 2 <= m:
        LOG *= 2
    total = 0
    for i in range(n):
        j = r[i]
        while j <= m:
            tree[j] += 1; j += j & -j
        if i >= w:
            j = r[i - w]
            while j <= m:
                tree[j] -= 1; j += j & -j
        if i >= w - 1:
            pos = 0; rem = k; step = LOG
            while step:
                q = pos + step
                if q <= m and tree[q] < rem:
                    pos = q; rem -= tree[q]
                step >>= 1
            total += vals[pos]
    print(total)
main()

import sys
def main():
    d = sys.stdin.buffer.read().split()
    n, m = int(d[0]), int(d[1])
    deg = [0] * (n + 1)
    us = list(map(int, d[2:2 + 2 * m:2])); vs = list(map(int, d[3:3 + 2 * m:2]))
    for u in us: deg[u] += 1
    for v in vs: deg[v] += 1
    out = [None] * (n + 1)
    for u, v in zip(us, vs):
        if deg[u] < deg[v] or (deg[u] == deg[v] and u < v):
            a, b = u, v
        else:
            a, b = v, u
        s = out[a]
        if s is None:
            out[a] = {b}
        else:
            s.add(b)
    cnt = [0] * (n + 1)
    T = 0
    for u in range(1, n + 1):
        ou = out[u]
        if ou is None:
            continue
        for v in ou:
            ov = out[v]
            if ov is not None:
                inter = ou & ov
                if inter:
                    k = len(inter)
                    T += k; cnt[u] += k; cnt[v] += k
                    for w in inter:
                        cnt[w] += 1
    best = 1
    for i in range(2, n + 1):
        if cnt[i] > cnt[best]:
            best = i
    print(T)
    print(best, cnt[best])
main()

import sys, heapq
def main():
    d = sys.stdin.buffer.read().split()
    s = d[0].decode()
    idx = 1
    bal = 0; cost = 0; h = []
    for ch in s:
        if ch == "(":
            bal += 1
        elif ch == ")":
            bal -= 1
        else:
            a = int(d[idx]); b = int(d[idx + 1]); idx += 2
            cost += b
            bal -= 1
            heapq.heappush(h, a - b)
        if bal < 0:
            if not h:
                print(-1); return
            cost += heapq.heappop(h)
            bal += 2
    print(cost if bal == 0 else -1)
main()
